-- ════════════════════════════════════════════════════════════════════════
-- PURULIA KASA — boundary data for the whole district
--
-- 20 CD blocks (OpenStreetMap, ODbL, simplified to ~150 m) and the Purulia
-- municipality wards (purulia_wards.geojson, simplified to ~5 m). Generated
-- by tools/build-areas.py; regenerate rather than edit. One statement per
-- object, no transaction wrapper, so it can also be loaded with EXECUTE.
--
-- Safe to re-run.
-- ════════════════════════════════════════════════════════════════════════

create table if not exists kasa_private.areas (
  id       text primary key,
  kind     text not null check (kind in ('block', 'ward')),
  name     text not null,
  ward_no  integer,
  min_lat  double precision not null,
  max_lat  double precision not null,
  min_lng  double precision not null,
  max_lng  double precision not null,
  polygons jsonb not null            -- [[outer ring, hole, ...], ...] as [lng, lat] pairs
);
create index if not exists areas_kind_idx on kasa_private.areas (kind);
alter table kasa_private.areas enable row level security;
revoke all on kasa_private.areas from public, anon, authenticated;

-- Generated by tools/build-areas.py. Do not edit by hand.
on conflict (id) do update set kind = excluded.kind, name = excluded.name, ward_no = excluded.ward_no,
  min_lat = excluded.min_lat, max_lat = excluded.max_lat, min_lng = excluded.min_lng, max_lng = excluded.max_lng,
  polygons = excluded.polygons;
